def transform(grid):
    out = [row[:] for row in grid]
    p9 = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 9]
    p7 = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 7]
    zeros = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 0]
    for r,c in p9: out[r][c] = 7
    if len(p7) > 1:
        for r,c in p7: out[r][c] = 2
    if p9 and p7 and p9[0][0] == p7[0][0]:
        rows = sorted(set(r for r,_ in p9))
        for c in sorted(set(c for _,c in zeros)):
            for r in rows:
                if grid[r][c] == 6: out[r][c] = 2
    elif p9 and p7:
        cols = sorted(set(c for _,c in p9))
        for r in sorted(set(r for r,_ in zeros)):
            for c in cols:
                if grid[r][c] == 6: out[r][c] = 2
    return out

